"""Disassemble generated byte arrays only. Read PE data; never load/call DLLs."""
from pathlib import Path
import json, hashlib, sys, struct
root=Path(__file__).resolve().parents[3]
sys.path[:0]=[str(root/'work/traction6000/vendor'),str(root/'work/traction6000/electrobrake/pydeps')]
import capstone, pefile
from capstone.x86 import X86_OP_IMM,X86_OP_MEM,X86_REG_EBX,X86_REG_EDI
folder=Path(__file__).parent/'managed-caves'
source=Path(__file__).parent/'TrainerContactVoltagePatch.cs'
expected='267d313214901309b98a6a0be00fd784d75c25def0dc2a473801009654dfaE57'.lower()
sha=lambda b:hashlib.sha256(b).hexdigest()
assert sha(source.read_bytes())==expected
generated=json.loads((folder/'generated-caves.json').read_text(encoding='utf-8-sig'))
assert generated['source_sha256'].lower()==expected
md=capstone.Cs(capstone.CS_ARCH_X86,capstone.CS_MODE_32);md.detail=True
checks=[]
def check(name,ok,detail):
 checks.append(dict(name=name,passed=bool(ok),evidence=detail))
 if not ok: raise AssertionError(name+': '+str(detail))
rows=[]; full=[]
for site in generated['sites']:
 name=site['name']; base=site['cave']; code=bytes.fromhex(site['hex']); ins=list(md.disasm(code,base))
 boundaries={x.address for x in ins}; end=base+len(code)
 check(name+' complete instruction decode',sum(x.size for x in ins)==len(code),len(code))
 check(name+' emitted binary exact',code==(folder/(name+'.bin')).read_bytes(),site['binary_sha256'])
 check(name+' binary SHA',sha(code)==site['binary_sha256'].lower(),sha(code))
 check(name+' no call/ret/x87',not any(x.mnemonic.startswith(('call','ret','f')) for x in ins),[x.mnemonic for x in ins])
 original=bytes.fromhex(site['original_hex'])
 prefix=original if site['sequential'] else b''
 check(name+' replay and save order',code.startswith(prefix+b'\x9c\x60'),(prefix+b'\x9c\x60').hex())
 check(name+' restore and continuation trailer',code[-7:-5]==b'\x61\x9d' and ins[-1].mnemonic=='jmp' and ins[-1].operands[0].imm==site['continuation'],hex(site['continuation']))
 check(name+' balanced saved registers/flags',sum(x.mnemonic=='pushal' for x in ins)==1 and sum(x.mnemonic=='popal' for x in ins)==1 and sum(x.mnemonic=='pushfd' for x in ins)==1 and sum(x.mnemonic=='popfd' for x in ins)==1,[x.mnemonic for x in ins if x.mnemonic.startswith(('push','pop'))])
 branches=[]
 for x in ins:
  if x.mnemonic.startswith('j'):
   target=x.operands[0].imm; external=x is ins[-1]
   check(name+' branch '+hex(x.address),target==site['continuation'] if external else target in boundaries and base<=target<end,hex(target))
   branches.append(dict(at=hex(x.address),asm=x.mnemonic+' '+x.op_str,target=hex(target),external=external))
  if x.mnemonic not in ('pushal','popal','pushfd','popfd'):
   _,written=x.regs_access()
   check(name+' no other ESP write '+hex(x.address),'esp' not in [x.reg_name(r) for r in written],x.mnemonic+' '+x.op_str)
 writes=[]
 allowed_state={20,24+site['index']*4,44+site['index']*4,64+site['index']*4,84+site['index']*4}
 for x in ins:
  for operand in x.operands:
   if operand.type==X86_OP_MEM and operand.access & capstone.CS_AC_WRITE:
    mem=operand.mem
    own_state=mem.base==X86_REG_EBX and mem.index==0 and mem.disp in allowed_state
    own_destination=mem.base==X86_REG_EDI and mem.index==0 and mem.disp==site['member_offset']
    check(name+' explicit write whitelist '+hex(x.address),own_state or own_destination,x.mnemonic+' '+x.op_str)
    writes.append(dict(at=hex(x.address),asm=x.mnemonic+' '+x.op_str,kind='owned_diagnostic_state' if own_state else 'guarded_Useti_or_ResT_Uset'))
 check(name+' one voltage store',sum(x['kind']=='guarded_Useti_or_ResT_Uset' for x in writes)==1,writes)
 # Every path through generated CFG must pass exactly one save and one restore;
 # termination is the sole original continuation and no instruction loops exist.
 by={x.address:x for x in ins}; paths=[]
 def walk(at,saved=0,flags=0,trail=()):
  assert at not in trail, 'generated CFG loop'
  x=by[at]; saved += (x.mnemonic=='pushal')-(x.mnemonic=='popal'); flags += (x.mnemonic=='pushfd')-(x.mnemonic=='popfd')
  assert saved in (0,1) and flags in (0,1)
  if x is ins[-1]:
   assert saved==0 and flags==0
   paths.append(len(trail)+1);return
  nexts=[x.address+x.size]
  if x.mnemonic=='jmp':nexts=[x.operands[0].imm]
  elif x.mnemonic.startswith('j'):nexts.append(x.operands[0].imm)
  for n in nexts:walk(n,saved,flags,trail+(at,))
 walk(base)
 check(name+' all CFG paths restore stack state',bool(paths),dict(paths=len(paths),min_instructions=min(paths),max_instructions=max(paths)))
 entry=bytes.fromhex(site['entry_jump_hex']);delta=struct.unpack('<i',entry[1:5])[0]
 check(name+' entry JMP exact target',entry[0]==0xe9 and site['module_base']+site['rva']+5+delta==base and len(entry)==len(original) and all(x==0x90 for x in entry[5:]),entry.hex())
 p32=lambda v:struct.pack('<I',v)
 fake=generated['fake_addresses']
 patterns={
  'owned diagnostic base':b'\xbb'+p32(fake['data']),
  'thread TEB unique thread comparison':bytes.fromhex('648b152400000081fa')+p32(generated['fake_thread'])+bytes.fromhex('0f85'),
  'expected destination comparison':b'\x3d'+p32(fake['tyga'] if site['sequential'] else site['destination'])+bytes.fromhex('0f85'),
  'native frame owner comparison':bytes.fromhex('8b55fc81fa')+p32(site['owner'])+bytes.fromhex('0f85'),
  'typed input pointer comparison':bytes.fromhex('8b4a0481f9')+p32(fake['pult'] if name=='Pult' else fake['tyga'])+bytes.fromhex('0f85'),
  'magic comparison':bytes.fromhex('813b')+p32(0x53564b55)+bytes.fromhex('0f85'),
  'previous fault skips store':bytes.fromhex('837b14000f85'),
  'whole volt unsigned upper limit':bytes.fromhex('8b530481fa')+p32(5040)+bytes.fromhex('0f87'),
  'checksum exact xor inputs':bytes.fromhex('8b4b088bf233f133730c81f6')+p32(0x53564b55)+bytes.fromhex('3b73100f85'),
  'generation nonzero':bytes.fromhex('837b0c000f84'),
  'live Eset equals integer source':bytes.fromhex('3915')+p32(fake['eset'])+bytes.fromhex('0f85'),
  'producer counter overflow trap':bytes((0xff,0x43,24+site['index']*4,0x0f,0x84))}
 patterns['other native input alias' if name=='Pult' else 'owned result alias']=(bytes.fromhex('8b4a0881f9')+p32(fake['tyga'])+bytes.fromhex('0f85') if name=='Pult' else bytes.fromhex('817927')+p32(fake['result'])+bytes.fromhex('0f85'))
 for label,pattern in patterns.items():check(name+' '+label,pattern in code,pattern.hex())
 asm=[dict(address=hex(x.address),bytes=x.bytes.hex(),asm=x.mnemonic+' '+x.op_str) for x in ins]
 full.append('\n'+name+'\n'+'\n'.join(x['address']+'  '+x['bytes'].ljust(22)+' '+x['asm'] for x in asm))
 rows.append(dict(name=name,cave=hex(base),continuation=hex(site['continuation']),length=len(code),branches=branches,writes=writes,cfg_paths=len(paths),instructions=asm))

entry=generated['sites'][-1]; block=bytes.fromhex(entry['hex'])
check('fifth hook exact replay',entry['name']=='TractionEntry' and bytes.fromhex(entry['original_hex'])==bytes.fromhex('8b45fc8b4004') and block.startswith(bytes.fromhex('8b45fc8b40049c60')),'mov eax,[ebp-4]; mov eax,[eax+4]; pushfd; pushad')
check('fifth hook permits both excitation inputs 0/1',bytes.fromhex('807816010f87') in block,'cmp byte ptr [eax+0x16],1; ja sourceFault. Unsigned 0/1 continue; values >1 reject.')
check('fifth hook skips active regenerative mode',bytes.fromhex('80ba00010000000f85') in block,'cmp byte ptr [edx+0x100],0; jne done (FFlagRecup !=0 retains calculated Uset).')
check('fifth hook retains roof-contact zero gate',bytes.fromhex('80b830010000000f85') in block and bytes.fromhex('33c9898f11000000') in block,'cmp [eax+0x130],0; jne seqPowered; xor ecx,ecx; mov [edi+0x11],ecx')
native=root/'work/trenager_static/WORK_TRENAGER_3D/RESOURCES/LOCOMOTIVES/1/Tyga1.dll'
blob=native.read_bytes();check('pinned PE read only SHA',sha(blob)=='8ec6a82e618a1d75cbb31242784084b530bb87308e601defc5263d5279270491',sha(blob))
