untouched=pe.get_data(0x17c352,10)
check('x87 continuation bytes outside replaced six MOV bytes',untouched.hex()=='dd0083c4fcd91c249b8b',untouched.hex())
check('pure managed generator scope',generated['x86'] and not generated['constructor_invoked'] and not generated['trainer_native_loaded'] and not generated['native_code_executed'],'Fake addresses only; BuildCave and Jump were generated, not executed.')
result=dict(schema_version=1,status='passed',source_sha256=expected,generated_manifest_sha256=sha((folder/'generated-caves.json').read_bytes()),generator_source_sha256=sha((Path(__file__).parent/'ContactVoltageCaveByteGenerator.cs').read_bytes()),generator_exe_sha256=sha((Path(__file__).parent/'ContactVoltageCaveByteGenerator.exe').read_bytes()),checks_total=len(checks),checks_passed=sum(x['passed'] for x in checks),native_executed=False,generated_instruction_bytes_executed=False,sites=rows,checks=checks,limits=['No constructor, install, runtime data guards, fault injection or live behavior tested.','Branches and store destinations are verified against generated fake-address CFG; native owner graph must still be guarded and tested separately.','Stack/flags are restored for all generated CFG paths; this does not execute x87 or prove native full RE conformity.'])
(folder/'capstone-disassembly.txt').write_text('\n'.join(full)+'\n',encoding='utf-8')
(folder/'bytecheck.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
